<?phpfunction afipservice_completesubstitutionarray(&$substitutionarray, $langs, $object) { global $conf, $db, $langs; $langs->load("\x61\146\151\160\x77\163\x40\x61\146\x69\x70\x77\163"); $sumQtyOffered = 0; $sumTotalOffered = 0; $substitutionarray["\x5f\123\x55\x4d\137\x51\124\x59\x5f\x4f\x46\x46\x45\122\x45\x44\x5f"] = 0; $substitutionarray["\x5f\123\x55\x4d\137\x54\117\x54\x41\114\x5f\117\x46\x46\x45\122\105\104\x5f"] = 0; $substitutionarray["\137\101\106\x49\120\127\123\137\117\x46\x46\105\122\105\104\137\x51\x54\x59\137\124\117\124\x41\x4c\x5f\x54\105\130\x54\x5f"] = ''; if ($object->lines) { $nblignes = count($object->lines); for ($i = 0; $i < $nblignes; $i++) { if ($object->lines[$i]->remise_percent == "\61\60\x30") { $sumQtyOffered += $object->lines[$i]->qty; if ($object->thirdparty->typent_code == "\x54\x45\x5f\x41\x5f\x52\111" || $object->thirdparty->typent_code == "\101") { $sumTotalOffered += $object->lines[$i]->qty * $object->lines[$i]->subprice; } else { $sumTotalOffered += $object->lines[$i]->qty * $object->lines[$i]->subprice * (1 + $object->lines[$i]->tva_tx / 100); } } } } if ($sumQtyOffered || $sumTotalOffered) { $substitutionarray["\x5f\123\x55\115\137\121\x54\x59\137\117\x46\x46\x45\122\105\x44\x5f"] = $sumQtyOffered; $substitutionarray["\137\123\125\115\137\124\x4f\124\x41\x4c\x5f\x4f\x46\x46\x45\122\105\x44\x5f"] = price($sumTotalOffered, 0, $langs, 1, 1); $substitutionarray["\x5f\x41\x46\x49\x50\x57\x53\137\x4f\106\x46\105\122\x45\104\137\x51\124\x59\x5f\124\x4f\124\x41\x4c\137\124\105\x58\x54\137"] = $sumQtyOffered . "\40" . $langs->trans("\101\106\111\120\x57\x53\x5f\x4f\x46\x46\x45\122\x45\x44\x5f\121\x54\x59\137\x54\x4f\124\101\114\x5f\x54\105\130\x54") . "\x20" . price($sumTotalOffered, 0, $langs, 1, 1); } }